    "required": true
   },
   {
    "name": "subject",
    "type": "string",
    "description": "The subject of the email.",
    "required": true
   },
   {
    "name": "body",
    "type": "string",
    "description": "The body of the email.",
    "required": true
   },
   {
    "name": "cc",
